import{_ as s}from"./chunks/nd2nz_conversion_half.D9um7pix.js";import{_ as t,o as l,a as n,b as p}from"./app.C41L12d5.js";const i="/ascendc.github.io/assets/enable_smallc0_nd2nz_conversion_half.ylPW65us.png",m=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"Memory矢量计算","link":"/api/SIMD-API/basic_api/memory_vector_compute/memory_vector_compute"},{"text":"数据搬运","link":"/api/SIMD-API/basic_api/memory_vector_compute/data_move/data_move"},{"text":"DataCopy（GM -> UB随路转换ND2NZ搬运）","link":"/api/SIMD-API/basic_api/memory_vector_compute/data_move/DataCopy_GMToUB_ND2NZ"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/memory_vector_compute/data_move/DataCopy_GMToUB_ND2NZ.md","filePath":"api/SIMD-API/basic_api/memory_vector_compute/data_move/DataCopy_GMToUB_ND2NZ.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"数据类型","slug":"数据类型","link":"#数据类型"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788159000000}'),e={name:"api/SIMD-API/basic_api/memory_vector_compute/data_move/DataCopy_GMToUB_ND2NZ.md"};function d(c,a,r,o,h,_){return l(),n("div",null,[...a[0]||(a[0]=[p(`<div><article class="markdown-body"><h1>DataCopy（GMToUB随路转换ND2NZ搬运）<span id="ZH-CN_TOPIC_0000002349187356"></span></h1><h2 id="产品支持情况">产品支持情况<span id="section1550532418810"></span><a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><div data-filter="x90"><ul><li>Kirin X90：不支持</li></ul></div><div data-filter="9030"><ul><li>Kirin 9030：不支持</li></ul></div><h2 id="功能说明">功能说明<span id="section12840195813362"></span><a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;basic_api/kernel_operator_data_copy_intf.h&quot;</code>。</p><p>该接口为软仿接口，从易用性角度出发进行设计，支持在从Global Memory到Unified Buffer（UB）的数据搬运过程中进行ND到NZ格式的转换。</p><p>具体支持的数据通路为（以<a href="../../aux_data_structures/TPosition.html">逻辑位置TPosition</a>表示）：</p><ul><li>Global Memory -&gt; UB <ul><li>GM -&gt; VECIN</li></ul></li></ul><h2 id="函数原型">函数原型<span id="section1954364615315"></span><a class="header-anchor" href="#函数原型">​</a></h2><ul><li><p>不支持enableSmallC0模式</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">DataCopy</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">GlobalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">Nd2NzParams</span><span class="o">&amp;</span><span class="w"> </span><span class="n">intriParams</span><span class="p">)</span>
</code></pre></div></li></ul><div data-filter="950"><ul><li><p>支持enableSmallC0模式（仅Ascend 950PR/Ascend 950DT支持）</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 该函数原型仅支持Ascend 950PR/Ascend 950DT</span>
<span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="p">,</span><span class="w"> </span><span class="kt">bool</span><span class="w"> </span><span class="n">enableSmallC0</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="nb">false</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">DataCopy</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">GlobalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">Nd2NzParams</span><span class="o">&amp;</span><span class="w"> </span><span class="n">intriParams</span><span class="p">)</span>
</code></pre></div></li></ul></div><h2 id="参数说明">参数说明<span id="section1251613311396"></span><a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 模板参数说明</p><table><thead><tr><th align="left">参数名</th><th align="left">描述</th></tr></thead><tbody><tr><td align="left">T</td><td align="left">源操作数或者目的操作数的数据类型。支持的数据类型请参考<a href="#section4219135304818">数据类型</a>。</td></tr><tr><td align="left">enableSmallC0</td><td align="left">SmallC0模式开关：当dValue小于等于4的时候，C0_SIZE会补齐到4 * sizeof(T)字节。<br>默认不开启。</td></tr></tbody></table><p><strong>表2</strong> 参数说明</p><table><thead><tr><th align="left">参数名</th><th align="center">输入/输出</th><th align="left">描述</th></tr></thead><tbody><tr><td align="left">dst</td><td align="center">输出</td><td align="left">目的操作数，类型为<a href="../../data_structures/LocalTensor/LocalTensor_intro.html">LocalTensor</a>。</td></tr><tr><td align="left">src</td><td align="center">输入</td><td align="left">源操作数，类型为<a href="../../data_structures/GlobalTensor/GlobalTensor_intro.html">GlobalTensor</a>。</td></tr><tr><td align="left">intriParams</td><td align="center">输入</td><td align="left">搬运参数，类型为Nd2NzParams，具体参数请参考<a href="#table_nd2nz_3">表3</a>。<br>具体定义请参考<code>\${INSTALL_DIR}/asc/include/basic_api/kernel_struct_data_copy.h</code>，<code>\${INSTALL_DIR}</code>请替换为CANN软件安装后文件存储路径。</td></tr></tbody></table><p><strong>表3</strong> Nd2NzParams结构体参数定义<span id="table_nd2nz_3"></span></p><table><thead><tr><th align="left">参数名</th><th align="left">描述</th></tr></thead><tbody><tr><td align="left">ndNum</td><td align="left">传输ND矩阵的数目，取值范围：ndNum∈[0, 4095]。</td></tr><tr><td align="left">nValue</td><td align="left">ND矩阵的行数，取值范围：nValue∈[0, 16384]。</td></tr><tr><td align="left">dValue</td><td align="left">ND矩阵的列数，取值范围：dValue∈[0, 65535]。</td></tr><tr><td align="left">srcNdMatrixStride</td><td align="left">源操作数相邻ND矩阵起始地址间的偏移，取值范围：srcNdMatrixStride∈[0, 65535]，单位为元素。</td></tr><tr><td align="left">srcDValue</td><td align="left">源操作数同一ND矩阵的相邻行起始地址间的偏移，取值范围：srcDValue∈[1, 65535]，单位为元素。</td></tr><tr><td align="left">dstNzC0Stride</td><td align="left">ND转换到NZ格式后，源操作数中的一行会转换为目的操作数的多行。dstNzC0Stride表示，目的NZ矩阵中，来自源操作数同一行的多行数据相邻行起始地址间的偏移，取值范围：dstNzC0Stride∈[1, 16384]，单位：C0_SIZE（32B）。</td></tr><tr><td align="left">dstNzNStride</td><td align="left">目的NZ矩阵中，Z型矩阵相邻行起始地址之间的偏移。取值范围：dstNzNStride∈[1, 16384]，单位：C0_SIZE（32B）。</td></tr><tr><td align="left">dstNzMatrixStride</td><td align="left">目的NZ矩阵中，相邻NZ矩阵起始地址间的偏移，取值范围：dstNzMatrixStride∈[1, 65535]，单位为元素。</td></tr></tbody></table><p>ND2NZ转换示意图如下，样例中参数设置值和解释说明如下：</p><ul><li>ndNum = 2，表示传输ND矩阵的数目为2 (ND矩阵1为A1~A2 + B1~B2，ND矩阵2为C1~C2 + D1~D2)。</li><li>nValue = 2，ND矩阵的行数，也就是矩阵的高度为2。</li><li>dValue = 24，ND矩阵的列数，也就是矩阵的宽度为24个元素。当dValue不满足32字节对齐时，在目的操作数中不足的部分会被补齐为0，例如图示中A2所在DataBlock的空白部分会被补齐为0。</li><li>srcNdMatrixStride = 144，表达相邻ND矩阵起始地址间的偏移，即为A1~C1的距离，即为9个DataBlock，9 * 16 = 144个元素。</li><li>srcDValue = 48，表示一行的所含元素个数，即为A1到B1的距离，即为3个DataBlock，3 * 16 = 48个元素。</li><li>dstNzC0Stride = 11。ND转换到NZ格式后，源操作数中的一行会转换为目的操作数的多行，例如src中A1和A2为1行，dst中A1和A2被分为2行。多行数据起始地址之间的偏移就是A1和A2在dst中的偏移，偏移为11个DataBlock。</li><li>dstNzNStride = 2，表示src中一个ND矩阵的第x行和第x+1行转换为NZ格式后在dst中的偏移，即A1和B1在dst之间的偏移为2个DataBlock。</li><li>dstNzMatrixStride = 96，表达dst中第x个ND矩阵的起点和第x+1个ND矩阵的起点的偏移，即A1和C1之间的距离，即为6个DataBlock，6 * 16 = 96个元素。</li></ul><p><strong>图1</strong> ND2NZ转换示意图（half数据类型）<span id="fig128961542184620"></span><br><img src="`+s+'" alt title="ND2NZ转换示意图（half数据类型）"></p><p>enableSmallC0开启模式下的ND2NZ转换示意图如下：</p><p><strong>图2</strong> enableSmallC0开启模式下的ND2NZ转换示意图（half数据类型）<span id="fig07641913195410"></span><br><img src="'+i+`" alt title="enableSmallC0开启模式下的ND2NZ转换示意图-（half数据类型）"></p><h2 id="数据类型">数据类型<span id="section4219135304818"></span><a class="header-anchor" href="#数据类型">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT，支持的数据类型为：bool、int8_t、uint8_t、hifloat8_t、fp8_e8m0_t、fp8_e5m2_t、fp8_e4m3fn_t、int16_t、uint16_t、half、bfloat16_t、int32_t、uint32_t、float、complex32。</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品，支持的数据类型为：int8_t、uint8_t、int16_t、uint16_t、half、bfloat16_t、int32_t、uint32_t、float。</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品，支持的数据类型为：int8_t、uint8_t、int16_t、uint16_t、half、bfloat16_t、int32_t、uint32_t、float。</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core，支持的数据类型为：int8_t、uint8_t、int16_t、uint16_t、half、int32_t、uint32_t、float。</li></ul></div><h2 id="返回值说明">返回值说明<span id="section446456163012"></span><a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<span id="section1140315215118"></span><a class="header-anchor" href="#约束说明">​</a></h2><ul><li><p>该接口为软仿接口，从易用性角度出发进行设计。</p></li><li><p>Nd2NzParams结构体参数的值需在取值范围内：</p><p><strong>表4</strong> Nd2NzParams结构体参数取值范围</p><table><thead><tr><th>参数名</th><th>取值范围</th></tr></thead><tbody><tr><td>ndNum</td><td>[0, 4095]</td></tr><tr><td>nValue</td><td>[0, 16384]</td></tr><tr><td>dValue</td><td>[0, 65535]</td></tr><tr><td>srcNdMatrixStride</td><td>[0, 65535]</td></tr><tr><td>srcDValue</td><td>[1, 65535]</td></tr><tr><td>dstNzC0Stride</td><td>[1, 16384]</td></tr><tr><td>dstNzNStride</td><td>[1, 16384]</td></tr><tr><td>dstNzMatrixStride</td><td>[1, 65535]</td></tr></tbody></table></li></ul><div data-filter="310p"><ul><li>针对Atlas 推理系列产品AI Core，需要预留8KB的UB空间，作为接口的临时数据存放区。</li></ul></div><h2 id="调用示例">调用示例<span id="section10309141400"></span><a class="header-anchor" href="#调用示例">​</a></h2><p>intriParams参数解析请参考<a href="#fig128961542184620">图1</a>。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// dstLocal为half类型的UB上的LocalTensor，srcGlobal为half类型的GlobalTensor。</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">Nd2NzParams</span><span class="w"> </span><span class="n">intriParams</span><span class="p">{</span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="mi">32</span><span class="p">,</span><span class="w"> </span><span class="mi">32</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="mi">32</span><span class="p">,</span><span class="w"> </span><span class="mi">32</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">};</span>
<span class="c1">// Global Memory -&gt; Local Memory</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopy</span><span class="p">(</span><span class="n">dstLocal</span><span class="p">,</span><span class="w"> </span><span class="n">srcGlobal</span><span class="p">,</span><span class="w"> </span><span class="n">intriParams</span><span class="p">);</span>
</code></pre></div><p>结果示例：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>输入数据(srcGlobal): [1 2 3 ... 1024]
输出数据(dstLocal):[1 2 ... 15 16 33 34 ... 47 48 65 66 ... 79 80 97 98 ... 111 112 ... 1009 1010... 1023 1024]
</code></pre></div></article></div>`,1)])])}const f=t(e,[["render",d]]);export{m as __pageData,f as default};
